-- CRM migration, applied only when explicitly enabled or in isolated test mode.
-- No SwiftCRM users, cards or production data are imported.
ALTER TABLE staff_permissions DROP CONSTRAINT staff_permissions_permission_check;
ALTER TABLE staff_permissions ADD CONSTRAINT staff_permissions_permission_check CHECK (permission IN ('orders','catalog','content','inventory','inventory_cost','service','contracts','finance','crm_boards_view','crm_cards_edit','crm_boards_manage','crm_cards_archive','crm_history_view','crm_cards_view_all'));
ALTER TABLE access_roles DROP CONSTRAINT access_roles_permissions_check;
ALTER TABLE access_roles ADD CONSTRAINT access_roles_permissions_check CHECK (permissions <@ ARRAY['orders','catalog','content','inventory','inventory_cost','service','contracts','finance','crm_boards_view','crm_cards_edit','crm_boards_manage','crm_cards_archive','crm_history_view','crm_cards_view_all']::text[]);
CREATE TABLE crm_work_boards (
 id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120), description TEXT NOT NULL DEFAULT '' CHECK (length(description)<=2000), position INTEGER NOT NULL DEFAULT 0 CHECK(position>=0), archived_at TIMESTAMPTZ, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), created_by TEXT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE crm_work_columns (
 id TEXT PRIMARY KEY, board_id TEXT NOT NULL REFERENCES crm_work_boards(id) ON DELETE RESTRICT, name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), color TEXT NOT NULL DEFAULT 'slate' CHECK(color ~ '^[a-z]{1,24}$'), position INTEGER NOT NULL CHECK(position>=0), archive_after_days INTEGER CHECK(archive_after_days BETWEEN 1 AND 3650), archived_at TIMESTAMPTZ, archived_by TEXT REFERENCES users(id), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(board_id,id), CHECK((archived_at IS NULL)=(archived_by IS NULL))
);
CREATE TABLE crm_work_cards (
 id TEXT PRIMARY KEY, board_id TEXT NOT NULL REFERENCES crm_work_boards(id) ON DELETE RESTRICT, column_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=10000), custom_data JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(custom_data)='object' AND pg_column_size(custom_data)<=65536), organization_id TEXT REFERENCES organizations(id) ON DELETE RESTRICT, request_id TEXT REFERENCES requests(id) ON DELETE RESTRICT, assigned_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, created_by TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), archived_at TIMESTAMPTZ, archived_by TEXT REFERENCES users(id), UNIQUE(board_id,id), FOREIGN KEY(board_id,column_id) REFERENCES crm_work_columns(board_id,id) ON DELETE RESTRICT, CHECK((archived_at IS NULL)=(archived_by IS NULL))
);
CREATE TABLE crm_work_field_definitions (
 id TEXT PRIMARY KEY, board_id TEXT NOT NULL REFERENCES crm_work_boards(id) ON DELETE RESTRICT, internal_name TEXT NOT NULL CHECK(internal_name ~ '^[a-z][a-z0-9_]{0,47}$'), display_name TEXT NOT NULL CHECK(length(trim(display_name)) BETWEEN 1 AND 120), field_type TEXT NOT NULL CHECK(field_type IN ('text','textarea','number','currency','date','time','checkbox','select','multiselect','email','phone','url')), position INTEGER NOT NULL DEFAULT 0 CHECK(position>=0), required BOOLEAN NOT NULL DEFAULT false, read_only BOOLEAN NOT NULL DEFAULT false, visible BOOLEAN NOT NULL DEFAULT true, show_on_preview BOOLEAN NOT NULL DEFAULT false, width TEXT NOT NULL DEFAULT 'half' CHECK(width IN ('half','full')), placeholder TEXT NOT NULL DEFAULT '' CHECK(length(placeholder)<=500), default_value JSONB, options JSONB NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(options)='array' AND pg_column_size(options)<=16384), config JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(config)='object' AND pg_column_size(config)<=16384), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(board_id,internal_name)
);
CREATE TABLE crm_work_card_events (
 id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, board_id TEXT NOT NULL REFERENCES crm_work_boards(id), card_id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL CHECK(length(action) BETWEEN 1 AND 80), details JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(details)='object' AND pg_column_size(details)<=16384), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(board_id,card_id) REFERENCES crm_work_cards(board_id,id)
);
CREATE FUNCTION crm_work_events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'CRM events are append only'; END $$;
CREATE TRIGGER crm_work_events_no_change BEFORE UPDATE OR DELETE ON crm_work_card_events FOR EACH ROW EXECUTE FUNCTION crm_work_events_immutable();
CREATE TABLE crm_work_board_events (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, board_id TEXT NOT NULL REFERENCES crm_work_boards(id), actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL CHECK(length(action) BETWEEN 1 AND 80), details JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(details)='object' AND pg_column_size(details)<=16384), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TRIGGER crm_work_board_events_no_change BEFORE UPDATE OR DELETE ON crm_work_board_events FOR EACH ROW EXECUTE FUNCTION crm_work_events_immutable();
CREATE TABLE crm_work_user_visibility (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT, scope TEXT NOT NULL CHECK(scope IN ('inherit','all','own')), updated_by TEXT NOT NULL REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE crm_work_visibility_history (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), actor_id TEXT NOT NULL REFERENCES users(id), old_scope TEXT NOT NULL CHECK(old_scope IN ('inherit','all','own')), new_scope TEXT NOT NULL CHECK(new_scope IN ('inherit','all','own')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TRIGGER crm_work_visibility_history_no_change BEFORE UPDATE OR DELETE ON crm_work_visibility_history FOR EACH ROW EXECUTE FUNCTION crm_work_events_immutable();
CREATE INDEX crm_work_columns_order_idx ON crm_work_columns(board_id,position,id);
CREATE INDEX crm_work_cards_board_idx ON crm_work_cards(board_id,archived_at,column_id,position,id);
CREATE INDEX crm_work_cards_assignee_idx ON crm_work_cards(assigned_user_id,board_id,archived_at);
CREATE INDEX crm_work_events_card_idx ON crm_work_card_events(card_id,created_at DESC,id DESC);
